function PageHeader({ eyebrow, title, description, action }: {eyebrow?: string, title: string, description: string, action?: React.ReactNode}) { return <div className="page-header">{eyebrow && <div className="eyebrow">{eyebrow}</div>}<div className="header-row"><div><h1>{title}</h1><p>{description}</p></div>{action}</div></div> }
function Card({ children, className = "" }: {children: React.ReactNode, className?: string}) { return <div className={`card ${className}`}>{children}</div> }
function Status({ children, tone = "green" }: {children: React.ReactNode, tone?: string}) { return <span className={`status-badge ${tone}`}><i/>{children}</span> }
function CopyButton({ text = "Copy" }: {text?: string}) { const [copied, setCopied] = useState(false); return <button className="copy-button" onClick={() => {setCopied(true); setTimeout(() => setCopied(false), 1200)}}>{copied ? <Check size={13}/> : <Copy size={13}/>} {copied ? "Copied" : text}</button> }

function ChatView() { const [message, setMessage] = useState(""); const [messages, setMessages] = useState<string[]>([]); const send = () => { const trimmed = message.trim(); if (!trimmed) return; setMessages(current => [...current, trimmed]); setMessage(""); }; return <><PageHeader eyebrow="BUILD / CHAT" title="Chat" description="Test models and explore responses in a focused workspace." action={<button className="button secondary" onClick={() => {setMessages([]); setMessage("")}}><Trash2 size={16}/> Clear</button>}/><div className="chat-shell"><div className="conversation-head"><div className="model-chip"><div className="model-glyph"><Bot size={15}/></div><div><strong>Veyra Core 70B</strong><span>veyra-core-70b</span></div><ChevronDown size={14}/></div><div className="conversation-actions"><span className="soft-label">{messages.length ? `${messages.length} messages` : "Unsaved conversation"}</span><button className="icon-button"><SlidersHorizontal size={16}/></button></div></div><div className="messages">{messages.length === 0 ? <div className="empty-chat"><div className="empty-mark"><Sparkles size={22}/></div><h2>What are you building?</h2><p>Start a conversation with Veyra. Ask a question, generate code, or explore an idea.</p><div className="prompt-suggestions"><button onClick={() => setMessage("Explain how streaming works in the Veyra API")}>Explain streaming in the API <ArrowUpRight size={14}/></button><button onClick={() => setMessage("Write a TypeScript function to summarize text")}>Write a TypeScript function <ArrowUpRight size={14}/></button></div></div> : <div className="message-list">{messages.map((item, index) => <div className="chat-message" key={`${item}-${index}`}><span className="avatar">JD</span><p>{item}</p></div>)}</div>}</div><div className="composer"><textarea value={message} onChange={e => setMessage(e.target.value)} onKeyDown={e => {if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing && e.keyCode !== 229) {e.preventDefault(); send()}}} placeholder="Message Veyra..."/><div className="composer-footer"><div className="composer-tools"><button className="tool-button"><Plus size={16}/></button><span>Core 70B</span><span className="separator-dot"/><span>128K context</span></div><div className="composer-meta"><kbd>Enter</kbd><span>to send</span><button className="send-button" aria-label="Send" onClick={send}><ArrowUpRight size={17}/></button></div></div></div></div></> }

function PlaygroundView() { const [tab, setTab] = useState("Request"); const [ran, setRan] = useState(false); return <><PageHeader eyebrow="BUILD / PLAYGROUND" title="Playground" description="Make requests, inspect responses, and generate production-ready code." action={<button className="button primary" onClick={() => {setRan(true); setTab("Response")}}><Play size={15}/> {ran ? "Run again" : "Run request"}</button>}/><div className="play-toolbar"><div className="method">POST</div><div className="endpoint"><span>https://api.veyra.ai</span>/v1/chat/completions</div><div className="toolbar-model"><Bot size={14}/> veyra-core-70b <ChevronDown size={13}/></div><span className="toolbar-spacer"/><button className="icon-button"><Settings size={16}/></button></div><div className="playground-grid"><Card className="panel"><div className="panel-tabs">{["Request", "Response", "Code"].map(t => <button key={t} className={tab === t ? "tab active" : "tab"} onClick={() => setTab(t)}>{t}</button>)}</div>{tab === "Request" ? <div className="request-body"><label>Messages</label><div className="message-editor"><div className="editor-role"><span className="role-dot user"/> user <ChevronDown size={13}/><button><Trash2 size={14}/></button></div><p>Write a concise explanation of how transformer models work.</p></div><button className="add-message"><Plus size={14}/> Add message</button><div className="parameter-header"><label>Parameters</label><button className="reset">Reset</button></div><div className="parameters"><div><span>Temperature</span><strong>0.7</strong></div><input type="range" defaultValue="70"/><div><span>Max tokens</span><strong>1024</strong></div><input type="range" defaultValue="45"/></div></div> : tab === "Response" ? <Response /> : <CodePanel />}</Card><Card className="panel response-panel"><div className="response-head"><div><label>Response</label><Status>200 OK</Status></div><span className="latency"><Timer size={13}/> 842ms</span></div><div className="response-content"><div className="response-placeholder"><Check size={18}/><span>Run the request to see the response</span><small>Your response will appear here</small></div></div><div className="response-foot"><span>Tokens <strong>— / —</strong></span><span>Model <strong>veyra-core-70b</strong></span></div></Card></div></> }
function Response() { return <div className="code-area"><pre>{`{\n  "id": "chatcmpl_7x92k",\n  "object": "chat.completion",\n  "model": "veyra-core-70b",\n  "choices": [\n    {\n      "index": 0,\n      "message": {\n        "role": "assistant",\n        "content": "A transformer is a neural network architecture..."\n      },\n      "finish_reason": "stop"\n    }\n  ]\n}`}</pre><CopyButton/></div> }
